  1→import { Fragment } from "react";
  2→import { cn } from "@/lib/utils";
  3→import { Badge } from "@/components/ui/badge";
  4→import { Button } from "@/components/ui/button";
  5→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  6→import { XCircle } from "lucide-react";
  7→import { STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
  8→import { format } from "date-fns";
  9→
 10→interface StageTrackerProps {
 11→  currentStage: HiringStage;
 12→  updatedAt?: string | null;
 13→  onStageChange: (stage: HiringStage) => void;
 14→  disabled?: boolean;
 15→}
 16→
 17→const STAGE_LABELS: Record<string, string> = {
 18→  applied: "Applied",
 19→  screened: "Screened",
 20→  interview: "Interview",
 21→  offer: "Offer",
 22→  hired: "Hired",
 23→};
 24→
 25→const StageTracker = ({ currentStage, updatedAt, onStageChange, disabled }: StageTrackerProps) => {
 26→  const currentIndex = currentStage === "rejected" ? -1 : STAGE_ORDER.indexOf(currentStage);
 27→  const isRejected = currentStage === "rejected";
 28→
 29→  return (
 30→    <div className="flex items-center gap-3 py-1">
 31→      <span className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider shrink-0">Stage</span>
 32→
 33→      {/* Dots + connectors + labels */}
 34→      <div className="flex-1 min-w-0">
 35→        {/* Top row: dots and connectors */}
 36→        <div className="flex items-center">
 37→          {STAGE_ORDER.map((stage, i) => {
 38→            const isCompleted = !isRejected && i < currentIndex;
 39→            const isCurrent = !isRejected && i === currentIndex;
 40→            const isUpcoming = isRejected || i > currentIndex;
 41→
 42→            return (
 43→              <Fragment key={stage}>
 44→                <TooltipProvider delayDuration={150}>
 45→                  <Tooltip>
 46→                    <TooltipTrigger asChild>
 47→                      <button
 48→                        disabled={disabled}
 49→                        onClick={(e) => { e.stopPropagation(); onStageChange(stage); }}
 50→                        className={cn(
 51→                          "relative w-6 h-6 rounded-full flex items-center justify-center text-[11px] font-bold transition-all duration-150 shrink-0",
 52→                          "focus:outline-none focus-visible:ring-2 focus-visible:ring-primary/40",
 53→                          isCompleted && "bg-emerald-500 text-white dark:bg-emerald-600 shadow-sm",
 54→                          isCurrent && "bg-primary text-primary-foreground ring-2 ring-primary/30 shadow-sm",
 55→                          isUpcoming && "bg-muted border border-border text-muted-foreground",
 56→                          !disabled && "cursor-pointer hover:scale-110 hover:shadow",
 57→                          disabled && "cursor-default"
 58→                        )}
 59→                      >
 60→                        {isCompleted ? "✓" : i + 1}
 61→                      </button>
 62→                    </TooltipTrigger>
 63→                    <TooltipContent className="text-xs">
 64→                      {isCompleted
 65→                        ? `${STAGE_LABELS[stage]} — done`
 66→                        : isCurrent
 67→                        ? `${STAGE_LABELS[stage]} — current stage`
 68→                        : `Move to ${STAGE_LABELS[stage]}`}
 69→                    </TooltipContent>
 70→                  </Tooltip>
 71→                </TooltipProvider>
 72→
 73→                {i < STAGE_ORDER.length - 1 && (
 74→                  <div className={cn(
 75→                    "h-px flex-1 min-w-[16px] max-w-[48px] transition-colors duration-200 shrink-0",
 76→                    i < currentIndex && !isRejected ? "bg-emerald-500" : "bg-border"
 77→                  )} />
 78→                )}
 79→              </Fragment>
 80→            );
 81→          })}
 82→        </div>
 83→
 84→        {/* Bottom row: labels aligned under each dot */}
 85→        <div className="flex items-start mt-1.5">
 86→          {STAGE_ORDER.map((stage, i) => {
 87→            const isCompleted = !isRejected && i < currentIndex;
 88→            const isCurrent = !isRejected && i === currentIndex;
 89→
 90→            return (
 91→              <Fragment key={stage}>
 92→                <span className={cn(
 93→                  "w-6 text-center text-[8px] leading-none",
 94→                  isCompleted && "text-emerald-600 dark:text-emerald-400",
 95→                  isCurrent && "text-primary font-semibold",
 96→                  !isCompleted && !isCurrent && "text-muted-foreground"
 97→                )}>
 98→                  {STAGE_LABELS[stage]}
 99→                </span>
100→                {i < STAGE_ORDER.length - 1 && (
101→                  <div className="flex-1 min-w-[16px] max-w-[48px]" />
102→                )}
103→              </Fragment>
104→            );
105→          })}
106→        </div>
107→      </div>
108→
109→      {/* Reject button — visible on all screen sizes */}
110→      <TooltipProvider delayDuration={150}>
111→        <Tooltip>
112→          <TooltipTrigger asChild>
113→            <Button
114→              variant="ghost"
115→              size="icon"
116→              disabled={disabled}
117→              className={cn(
118→                "h-7 w-7 shrink-0",
119→                isRejected
120→                  ? "text-destructive bg-destructive/10 hover:bg-destructive/20"
121→                  : "text-muted-foreground/40 hover:text-destructive hover:bg-destructive/10"
122→              )}
123→              onClick={(e) => { e.stopPropagation(); onStageChange("rejected"); }}
124→            >
125→              <XCircle className="h-3.5 w-3.5" />
126→            </Button>
127→          </TooltipTrigger>
128→          <TooltipContent className="text-xs">
129→            {isRejected ? "Click any stage to restore" : "Reject candidate"}
130→          </TooltipContent>
131→        </Tooltip>
132→      </TooltipProvider>
133→
134→      {/* Rejected badge */}
135→      {isRejected && (
136→        <Badge variant="destructive" className="text-[11px] shrink-0">Rejected</Badge>
137→      )}
138→
139→      {/* Updated timestamp */}
140→      {updatedAt && (() => {
141→        try {
142→          return (
143→            <span className="text-[11px] text-muted-foreground shrink-0">
144→              Updated {format(new Date(updatedAt), "MMM d")}
145→            </span>
146→          );
147→        } catch {
148→          return null;
149→        }
150→      })()}
151→    </div>
152→  );
153→};
154→
155→export default StageTracker;
156→

  1→import { useState } from "react";
  2→import { ChevronDown, ChevronUp } from "lucide-react";
  3→import { Card, CardContent, CardHeader } from "@/components/ui/card";
  4→import { Badge } from "@/components/ui/badge";
  5→import { Progress } from "@/components/ui/progress";
  6→import type { Result } from "@/pages/Index";
  7→
  8→interface SkillsDetailPanelProps {
  9→  result: Result;
 10→}
 11→
 12→type SkillLevel = "Expert" | "Adv" | "Good" | "Mid" | "Low" | "Gap";
 13→
 14→const getSkillLevel = (score: number): SkillLevel => {
 15→  if (score >= 90) return "Expert";
 16→  if (score >= 70) return "Adv";
 17→  if (score >= 55) return "Good";
 18→  if (score >= 40) return "Mid";
 19→  if (score >= 20) return "Low";
 20→  return "Gap";
 21→};
 22→
 23→const SkillsDetailPanel = ({ result: r }: SkillsDetailPanelProps) => {
 24→  const [showAll, setShowAll] = useState(false);
 25→  const scores = r.category_scores_json;
 26→
 27→  const entries = scores && typeof scores === "object" && !Array.isArray(scores)
 28→    ? Object.entries(scores as Record<string, any>).map(([skill, data]) => {
 29→        const score = data && typeof data === "object" ? (data.score ?? 0) : (typeof data === "number" ? data : 0);
 30→        const clamped = Math.max(0, Math.min(score, 100));
 31→        return { skill, score: clamped, level: getSkillLevel(clamped) };
 32→      }).sort((a, b) => b.score - a.score)
 33→    : [];
 34→
 35→  const skillCount = entries.length;
 36→  const overallScore = skillCount > 0
 37→    ? Math.round(entries.reduce((sum, e) => sum + e.score, 0) / skillCount)
 38→    : 0;
 39→
 40→  const topSkills = entries.filter((e) => e.score >= 40).slice(0, 5);
 41→  const gapSkills = entries.filter((e) => e.score < 40);
 42→
 43→  return (
 44→    <Card>
 45→      <CardHeader className="pb-3 px-4 pt-4 flex-row items-center gap-2 space-y-0">
 46→        <h4 className="text-sm font-medium text-foreground">Skills</h4>
 47→        {skillCount > 0 && <Badge variant="secondary" className="text-[11px] h-5">{skillCount}</Badge>}
 48→      </CardHeader>
 49→      <CardContent className="px-4 pb-4 pt-0 space-y-4">
 50→        {skillCount > 0 ? (
 51→          <>
 52→            {/* Score */}
 53→            <div className="space-y-2">
 54→              <div className="flex items-baseline gap-1">
 55→                <span className="text-2xl font-semibold tabular-nums text-foreground">{overallScore}</span>
 56→                <span className="text-xs text-muted-foreground">/100</span>
 57→              </div>
 58→              <Progress value={overallScore} className="h-1.5" />
 59→            </div>
 60→
 61→            {/* Top skills */}
 62→            {topSkills.length > 0 && (
 63→              <div className="flex flex-wrap gap-1.5">
 64→                {topSkills.map((s) => (
 65→                  <Badge key={s.skill} variant="secondary" className="text-xs font-normal">
 66→                    {s.skill.replace(/_/g, " ")} · {s.level}
 67→                  </Badge>
 68→                ))}
 69→              </div>
 70→            )}
 71→
 72→            {/* Gaps */}
 73→            {gapSkills.length > 0 && (
 74→              <div className="space-y-1.5 pt-3 border-t border-border">
 75→                <h5 className="text-xs text-muted-foreground font-medium">Gaps</h5>
 76→                {gapSkills.map((s) => (
 77→                  <div key={s.skill} className="flex items-center justify-between text-sm py-0.5">
 78→                    <span className="text-muted-foreground capitalize">{s.skill.replace(/_/g, " ")}</span>
 79→                    <Badge variant="outline" className="text-[11px] h-5">{s.level}</Badge>
 80→                  </div>
 81→                ))}
 82→              </div>
 83→            )}
 84→
 85→            {/* Expand */}
 86→            {entries.length > 5 && (
 87→              <button
 88→                className="flex items-center justify-center gap-1 w-full text-xs text-muted-foreground hover:text-foreground transition-colors"
 89→                onClick={() => setShowAll(!showAll)}
 90→              >
 91→                {showAll ? "Hide" : `View all ${skillCount}`}
 92→                {showAll ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
 93→              </button>
 94→            )}
 95→
 96→            {showAll && (
 97→              <div className="space-y-1 pt-2 border-t border-border">
 98→                {entries.map((e) => (
 99→                  <div key={e.skill} className="flex items-center justify-between text-sm py-0.5">
100→                    <span className="text-muted-foreground capitalize truncate">{e.skill.replace(/_/g, " ")}</span>
101→                    <Badge variant="outline" className="text-[11px] h-5 shrink-0">{e.level}</Badge>
102→                  </div>
103→                ))}
104→              </div>
105→            )}
106→          </>
107→        ) : (
108→          <p className="text-sm text-muted-foreground">No skill data</p>
109→        )}
110→      </CardContent>
111→    </Card>
112→  );
113→};
114→
115→export default SkillsDetailPanel;
