306→            {certifications.map((cert, i) => (
307→              <Badge key={i} variant="outline" className="text-[11px]">{cert}</Badge>
308→            ))}
309→          </div>
310→        </div>
311→      )}
312→    </div>
313→  );
314→};
315→
316→export default EducationPanel;
