 17→
 18→interface ConfidenceReportProps {
 19→  results: Result[];
 20→}
 21→
 22→interface BucketEntry {
 23→  label: string;
 24→  count: number;
 25→  range: string;
 26→}
 27→
 28→const getConfidenceBadge = (
 29→  avg: number
 30→): { label: string; variant: "default" | "secondary" | "destructive" | "outline" } => {
 31→  if (avg >= 75) return { label: "High", variant: "default" };
 32→  if (avg >= 45) return { label: "Medium", variant: "secondary" };
 33→  return { label: "Low", variant: "destructive" };
 34→};
 35→
 36→const ConfidenceReport = ({ results }: ConfidenceReportProps) => {
 37→  const [open, setOpen] = useState(false);
 38→
 39→  const scored = results.filter((r) => !r.pending && r.overall_score > 0);
 40→  if (scored.length === 0) return null;
 41→
 42→  // 1. Overall AI Confidence
 43→  const avgConfidence = Math.round(
 44→    scored.reduce((sum, r) => sum + (r.confidence ?? 0), 0) / scored.length
 45→  );
 46→
 47→  // 2. Per-Dimension averages from category_scores_json
 48→  const dimensionTotals: Record<string, { total: number; count: number }> = {};
 49→  for (const r of scored) {
 50→    if (!r.category_scores_json || typeof r.category_scores_json !== "object") continue;
 51→    for (const [key, val] of Object.entries(
 52→      r.category_scores_json as Record<string, { score: number }>
 53→    )) {
 54→      if (!dimensionTotals[key]) dimensionTotals[key] = { total: 0, count: 0 };
 55→      dimensionTotals[key].total += val.score ?? 0;
 56→      dimensionTotals[key].count += 1;
 57→    }
 58→  }
 59→  const dimensions = Object.entries(dimensionTotals).map(([name, { total, count }]) => ({
 60→    name,
 61→    avg: Math.round(total / count),
 62→  }));
 63→
 64→  // 3. Score distribution buckets
 65→  const buckets: BucketEntry[] = [
 66→    { label: "Weak", range: "0–25%", count: 0 },
 67→    { label: "Below Avg", range: "26–50%", count: 0 },
 68→    { label: "Good", range: "51–75%", count: 0 },
 69→    { label: "Strong", range: "76–100%", count: 0 },
 70→  ];
 71→  for (const r of scored) {
 72→    const s = r.overall_score;
 73→    if (s <= 25) buckets[0].count++;
 74→    else if (s <= 50) buckets[1].count++;
 75→    else if (s <= 75) buckets[2].count++;
 76→    else buckets[3].count++;
 77→  }
 78→  const chartData = buckets.map((b) => ({ name: b.label, count: b.count, range: b.range }));
 79→
 80→  const { label: confidenceLabel, variant: confidenceVariant } = getConfidenceBadge(avgConfidence);
 81→
 82→  const formatDimensionName = (key: string) =>
 83→    key
 84→      .replace(/_/g, " ")
 85→      .replace(/\b\w/g, (c) => c.toUpperCase());
 86→
 87→  return (
 88→    <Collapsible open={open} onOpenChange={setOpen}>
 89→      <Card>
 90→        <CollapsibleTrigger asChild>
 91→          <CardHeader className="pb-3 cursor-pointer select-none hover:bg-muted/30 transition-colors rounded-t-lg">
 92→            <div className="flex items-center justify-between">
 93→              <div className="flex items-center gap-2">
 94→                <div className="w-7 h-7 rounded-md bg-primary/10 flex items-center justify-center shrink-0">
 95→                  <Brain className="h-4 w-4 text-primary" />
 96→                </div>
 97→                <CardTitle className="text-base">AI Confidence Score</CardTitle>
 98→                <Badge variant={confidenceVariant} className="text-[11px] px-1.5 py-0">
 99→                  {confidenceLabel}
100→                </Badge>
101→              </div>
102→              <div className="flex items-center gap-3">
103→                <span className="text-sm font-semibold tabular-nums text-primary">
104→                  {avgConfidence}/100
105→                </span>
106→                {open ? (
107→                  <ChevronUp className="h-4 w-4 text-muted-foreground" />
108→                ) : (
109→                  <ChevronDown className="h-4 w-4 text-muted-foreground" />
110→                )}
111→              </div>
112→            </div>
113→          </CardHeader>
114→        </CollapsibleTrigger>
115→
116→        <CollapsibleContent>
117→          <CardContent className="pt-0 space-y-6">
118→            {/* Overall confidence bar */}
119→            <div className="space-y-1.5">
120→              <div className="flex items-center justify-between text-xs text-muted-foreground">
121→                <span>Average AI confidence across {scored.length} candidate{scored.length !== 1 ? "s" : ""}</span>
122→                <span className="font-medium text-foreground tabular-nums">{avgConfidence}%</span>
123→              </div>
124→              <Progress value={avgConfidence} className="h-2" />
125→            </div>
126→
127→            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
128→              {/* Per-Dimension scores */}
129→              {dimensions.length > 0 && (
130→                <div className="space-y-3">
131→                  <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
132→                    Scoring Dimensions
133→                  </p>
134→                  <div className="space-y-2.5">
135→                    {dimensions.map((dim) => (
136→                      <div key={dim.name} className="space-y-1">
137→                        <div className="flex items-center justify-between">
138→                          <span className="text-xs font-medium text-foreground">
139→                            {formatDimensionName(dim.name)}
140→                          </span>
141→                          <span
142→                            className={cn(
143→                              "text-xs font-semibold tabular-nums",
144→                              dim.avg >= 70
145→                                ? "text-score-skills"
146→                                : dim.avg >= 40
147→                                ? "text-warning"
148→                                : "text-destructive"
149→                            )}
150→                          >
151→                            {dim.avg}%
152→                          </span>
153→                        </div>
154→                        <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
155→                          <div
156→                            className={cn(
157→                              "h-full rounded-full transition-all duration-500",
158→                              dim.avg >= 70
159→                                ? "bg-score-skills"
160→                                : dim.avg >= 40
161→                                ? "bg-warning"
