227→                    >
228→                      <span className="text-[11px] text-muted-foreground">{b.label}</span>
229→                      <span className="text-[11px] font-semibold tabular-nums text-foreground">
230→                        {b.count}
231→                      </span>
232→                    </div>
233→                  ))}
234→                </div>
235→              </div>
236→            </div>
237→          </CardContent>
238→        </CollapsibleContent>
239→      </Card>
240→    </Collapsible>
241→  );
242→};
